import { nodeResolve } from "@rollup/plugin-node-resolve";
import ignore from "rollup-plugin-ignore";
import commonjs from "@rollup/plugin-commonjs";
import typescript from "@rollup/plugin-typescript";

export default {
  input: "src/index.ts",
  output: [
    {
      file: "lib/index.js",
      exports: "named",
      format: "es",
      sourcemap: true,
      globals: { ws: "ws", perf_hooks: "perf_hooks" },
    },
  ],
  plugins: [
    ignore(["fs", "path", "crypto", "node:fs", "node:path", "node:crypto"]),
    nodeResolve({ browser: true }),
    commonjs({
      ignoreDynamicRequires: true,
    }),
    typescript({
      tsconfig: "./tsconfig.json",
    }),
  ],
};

export {
  ModelRecord,
  AppConfig,
  OPFSAccessMode,
  ChatOptions,
  MLCEngineConfig,
  GenerationConfig,
  ModelType,
  prebuiltAppConfig,
  modelVersion,
  modelLibURLPrefix,
  functionCallingModelIds,
} from "./config";

export {
  verifyIntegrity,
  isValidSRI,
  type ModelIntegrity,
  type SRIString,
  type FileIntegrityMap,
} from "./integrity";

export { IntegrityError } from "./error";

export {
  InitProgressCallback,
  InitProgressReport,
  MLCEngineInterface,
  LogitProcessor,
  LogLevel,
} from "./types";

export { MLCEngine, CreateMLCEngine } from "./engine";

export {
  hasModelInCache,
  deleteChatConfigInCache,
  deleteModelAllInfoInCache,
  deleteModelWasmInCache,
  deleteModelInCache,
} from "./cache_util";

export {
  WebWorkerMLCEngineHandler,
  WebWorkerMLCEngine,
  CreateWebWorkerMLCEngine,
} from "./web_worker";

export { WorkerRequest, WorkerResponse, CustomRequestParams } from "./message";

export {
  ServiceWorkerMLCEngineHandler,
  ServiceWorkerMLCEngine,
  CreateServiceWorkerMLCEngine,
} from "./service_worker";

export {
  ServiceWorkerMLCEngineHandler as ExtensionServiceWorkerMLCEngineHandler,
  ServiceWorkerMLCEngine as ExtensionServiceWorkerMLCEngine,
  CreateServiceWorkerMLCEngine as CreateExtensionServiceWorkerMLCEngine,
} from "./extension_service_worker";

export * from "./openai_api_protocols/index";

module.exports = {
    preset: "ts-jest",
    testEnvironment: "node",
    roots: ["<rootDir>/tests", "<rootDir>/src"],
    modulePathIgnorePatterns: ["<rootDir>/examples/"],
    collectCoverageFrom: ["src/**/*.{ts,tsx}", "!src/**/*.d.ts"],
    coverageThreshold: {
        global: {
            statements: 25,
            branches: 20,
            functions: 20,
            lines: 25,
        },
        "./src/engine.ts": {
            statements: 35,
            branches: 25,
            functions: 40,
            lines: 35,
        },
    },
};

